// Lab is a type, so importing it as a value is refused under verbatimModuleSyntax.
import { Lab } from './model.ts';
export function describe(lab: Lab): string {
  return lab.code + ' (' + lab.seats + ')';
}

import { describe } from '../src/describe.ts';
const s: string = describe({ code: 'BE-201', seats: 40 });
export { s };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { describe } from '../src/describe.ts';
test('describe', () => assert.equal(describe({ code: 'BE-201', seats: 40 }), 'BE-201 (40)'));

